1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node.js built-ins only. Run with `node server.mjs`.
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import fsp from 'node:fs/promises';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const MAX_PORT = 65535;
12	const DEFAULT_DATA_FILE = 'bookings.json';
13	const MAX_BODY_BYTES = 10000;
14	const MAX_TITLE_LENGTH = 80;
15	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
16	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
17	const JSON_TYPE = 'application/json; charset=utf-8';
18	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
19	const STATIC_FILES = Object.freeze({
20	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
21	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
22	});
23	const BOOKING_PREFIX = '/api/bookings/';
24	
25	const MSG = Object.freeze({
26	  notFound: 'not found',
27	  methodNotAllowed: 'method not allowed',
28	  internal: 'internal error',
29	  bookingNotFound: 'booking not found',
30	  contentType: 'content type must be application/json',
31	  tooLarge: 'body too large',
32	  notObject: 'body must be a JSON object',
33	  room: `room must be one of ${ROOMS.join(', ')}`,
34	  title: `title must be 1 to ${MAX_TITLE_LENGTH} characters`,
35	  date: 'date must be a valid YYYY-MM-DD date',
36	  start: 'start must be HH:MM',
37	  end: 'end must be HH:MM',
38	  order: 'end must be after start',
39	});
40	
41	class HttpError extends Error {
42	  constructor(status, message) {
43	    super(message);
44	    this.status = status;
45	  }
46	}
47	
48	// ---------- validation ----------
49	
50	const DATE_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
51	const TIME_RE = /^([01][0-9]|2[0-3]):[0-5][0-9]$/;
52	
53	function daysInMonth(year, month) {
54	  if (month === 2) return year % 4 === 0 ? 29 : 28;
55	  return [4, 6, 9, 11].includes(month) ? 30 : 31;
56	}
57	
58	function isValidDate(value) {
59	  if (typeof value !== 'string') return false;
60	  const match = DATE_RE.exec(value);
61	  if (!match) return false;
62	  const [year, month, day] = match.slice(1).map(Number);
63	  if (year < 2000 || year > 2099 || month < 1 || month > 12) return false;
64	  return day >= 1 && day <= daysInMonth(year, month);
65	}
66	
67	function isValidTime(value) {
68	  return typeof value === 'string' && TIME_RE.test(value);
69	}
70	
71	function isPlainObject(value) {
72	  return typeof value === 'object' && value !== null && !Array.isArray(value);
73	}
74	
75	function field(body, key) {
76	  return Object.hasOwn(body, key) ? body[key] : undefined;
77	}
78	
79	/** Applies booking rules 4-9; returns the normalised fields or throws HttpError 400. */
80	function validateFields(body) {
81	  const room = field(body, 'room');
82	  if (typeof room !== 'string' || !ROOMS.includes(room)) throw new HttpError(400, MSG.room);
83	  const rawTitle = field(body, 'title');
84	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : null;
85	  if (title === null || title.length < 1 || title.length > MAX_TITLE_LENGTH) {
86	    throw new HttpError(400, MSG.title);
87	  }
88	  const date = field(body, 'date');
89	  if (!isValidDate(date)) throw new HttpError(400, MSG.date);
90	  const start = field(body, 'start');
91	  if (!isValidTime(start)) throw new HttpError(400, MSG.start);
92	  const end = field(body, 'end');
93	  if (!isValidTime(end)) throw new HttpError(400, MSG.end);
94	  if (!(end > start)) throw new HttpError(400, MSG.order);
95	  return { room, title, date, start, end };
96	}
97	
98	function findOverlap(bookings, candidate) {
99	  const clashes = bookings.filter((b) => b.room === candidate.room && b.date === candidate.date
100	    && b.start < candidate.end && candidate.start < b.end);
101	  return clashes.reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
102	}
103	
104	function compareBookings(a, b) {
105	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
106	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
107	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
108	}
109	
110	// ---------- data file ----------
111	
112	function isStoredBooking(b, nextId) {
113	  if (!isPlainObject(b)) return false;
114	  const keys = Object.keys(b);
115	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
116	  if (!Number.isSafeInteger(b.id) || b.id < 1 || b.id >= nextId) return false;
117	  try {
118	    const fields = validateFields(b);
119	    return fields.title === b.title;
120	  } catch (err) {
121	    if (err instanceof HttpError) return false;
122	    throw err;
123	  }
124	}
125	
126	/** Returns a frozen state or null when the content is not in this server's layout. */
127	function parseState(text) {
128	  let data;
129	  try {
130	    data = JSON.parse(text);
131	  } catch {
132	    return null; // invalid JSON is reported by the caller as an unreadable data file
133	  }
134	  if (!isPlainObject(data) || !Number.isSafeInteger(data.nextId) || data.nextId < 1) return null;
135	  if (!Array.isArray(data.bookings)) return null;
136	  if (!data.bookings.every((b) => isStoredBooking(b, data.nextId))) return null;
137	  if (new Set(data.bookings.map((b) => b.id)).size !== data.bookings.length) return null;
138	  const clash = data.bookings.some((b, i) => findOverlap(data.bookings.slice(0, i), b) !== null);
139	  if (clash) return null;
140	  return freezeState({ nextId: data.nextId, bookings: data.bookings });
141	}
142	
143	function freezeState({ nextId, bookings }) {
144	  return Object.freeze({ nextId, bookings: Object.freeze(bookings.map((b) => Object.freeze({ ...b }))) });
145	}
146	
147	/** Reads the data file once; returns the state or null when it cannot be used. */
148	function loadState(filePath) {
149	  let text;
150	  try {
151	    text = fs.readFileSync(filePath, 'utf8');
152	  } catch (err) {
153	    if (err.code === 'ENOENT') return freezeState({ nextId: 1, bookings: [] });
154	    return null;
155	  }
156	  return parseState(text);
157	}
158	
159	let tempCounter = 0;
160	
161	async function saveState(filePath, state) {
162	  tempCounter += 1;
163	  const tempPath = `${filePath}.${process.pid}.${tempCounter}.tmp`;
164	  const json = JSON.stringify({ nextId: state.nextId, bookings: state.bookings });
165	  try {
166	    await fsp.writeFile(tempPath, json, { flag: 'wx' });
167	    await fsp.rename(tempPath, filePath);
168	  } catch (err) {
169	    await fsp.rm(tempPath, { force: true }).catch((rmErr) => logError('temp cleanup failed', rmErr));
170	    throw err;
171	  }
172	}
173	
174	// ---------- HTTP plumbing ----------
175	
176	function logError(context, err) {
177	  process.stderr.write(`${context}: ${err && err.message ? err.message : String(err)}\n`);
178	}
179	
180	function readBody(req) {
181	  return new Promise((resolve, reject) => {
182	    const chunks = [];
183	    let size = 0;
184	    req.on('data', (chunk) => {
185	      size += chunk.length;
186	      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
187	    });
188	    req.on('end', () => resolve({ size, buffer: size <= MAX_BODY_BYTES ? Buffer.concat(chunks) : null }));
189	    req.on('error', reject);
190	  });
191	}
192	
193	function send(res, status, body, type = JSON_TYPE) {
194	  if (body === undefined) {
195	    res.writeHead(status);
196	    res.end();
197	    return;
198	  }
199	  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
200	  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(payload) });
201	  res.end(payload);
202	}
203	
204	function sendError(res, status, message) {
205	  send(res, status, { error: message });
206	}
207	
208	function mediaType(header) {
209	  if (typeof header !== 'string') return null;
210	  return header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase();
211	}
212	
213	function parseJsonObject(buffer) {
214	  try {
215	    const value = JSON.parse(buffer.toString('utf8'));
216	    return isPlainObject(value) ? value : null;
217	  } catch {
218	    return null; // any parse failure means the body is not a JSON object (rule 3)
219	  }
220	}
221	
222	// ---------- app ----------
223	
224	function createApp(dataPath, initialState) {
225	  let state = initialState;
226	  let queue = Promise.resolve();
227	
228	  /** Runs mutations one at a time so concurrent requests behave sequentially. */
229	  function serialize(task) {
230	    const run = queue.then(task);
231	    queue = run.catch(() => undefined); // the failure is handled by the caller awaiting `run`
232	    return run;
233	  }
234	
235	  async function commit(nextState) {
236	    const frozen = freezeState(nextState);
237	    await saveState(dataPath, frozen);
238	    state = frozen;
239	  }
240	
241	  function listBookings(query) {
242	    const params = new URLSearchParams(query);
243	    let bookings = [...state.bookings];
244	    if (params.has('date')) {
245	      const date = params.get('date');
246	      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
247	      bookings = bookings.filter((b) => b.date === date);
248	    }
249	    return { bookings: bookings.sort(compareBookings) };
250	  }
251	
252	  function createBooking(req, body) {
253	    if (mediaType(req.headers['content-type']) !== 'application/json') {
254	      throw new HttpError(415, MSG.contentType);
255	    }
256	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
257	    const parsed = parseJsonObject(body.buffer);
258	    if (parsed === null) throw new HttpError(400, MSG.notObject);
259	    const fields = validateFields(parsed);
260	    return serialize(async () => {
261	      const clash = findOverlap(state.bookings, fields);
262	      if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
263	      const booking = { id: state.nextId, ...fields };
264	      await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
265	      return booking;
266	    });
267	  }
268	
269	  function deleteBooking(idText) {
270	    return serialize(async () => {
271	      const id = /^[1-9][0-9]*$/.test(idText) ? Number(idText) : NaN;
272	      if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
273	      await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
274	    });
275	  }
276	
277	  async function serveStatic(res, entry) {
278	    const content = await fsp.readFile(path.join(PUBLIC_DIR, entry.file));
279	    send(res, 200, content, entry.type);
280	  }
281	
282	  /** Resolves the route for a raw path; returns null when the path is unknown. */
283	  function route(pathName, query, req, body, res) {
284	    if (pathName === '/api/rooms') return { GET: () => send(res, 200, { rooms: ROOMS }) };
285	    if (pathName === '/api/bookings') {
286	      return {
287	        GET: () => send(res, 200, listBookings(query)),
288	        POST: async () => send(res, 201, await createBooking(req, body)),
289	      };
290	    }
291	    if (pathName.startsWith(BOOKING_PREFIX)) {
292	      const id = pathName.slice(BOOKING_PREFIX.length);
293	      if (id === '' || id.includes('/')) return null;
294	      return { DELETE: async () => { await deleteBooking(id); send(res, 204); } };
295	    }
296	    if (Object.hasOwn(STATIC_FILES, pathName)) {
297	      return { GET: () => serveStatic(res, STATIC_FILES[pathName]) };
298	    }
299	    return null;
300	  }
301	
302	  async function handle(req, res) {
303	    const body = await readBody(req);
304	    const target = req.url;
305	    const queryStart = target.indexOf('?');
306	    const pathName = queryStart === -1 ? target : target.slice(0, queryStart);
307	    const query = queryStart === -1 ? '' : target.slice(queryStart + 1);
308	    const handlers = route(pathName, query, req, body, res);
309	    if (handlers === null) return sendError(res, 404, MSG.notFound);
310	    if (!Object.hasOwn(handlers, req.method)) return sendError(res, 405, MSG.methodNotAllowed);
311	    return handlers[req.method]();
312	  }
313	
314	  return async function onRequest(req, res) {
315	    try {
316	      await handle(req, res);
317	    } catch (err) {
318	      if (err instanceof HttpError) {
319	        sendError(res, err.status, err.message);
320	        return;
321	      }
322	      logError('request failed', err);
323	      if (!res.headersSent) sendError(res, 500, MSG.internal);
324	      else res.destroy();
325	    }
326	  };
327	}
328	
329	// ---------- startup ----------
330	
331	function parsePort(raw) {
332	  if (raw === undefined || raw === '') return DEFAULT_PORT;
333	  if (!/^[0-9]+$/.test(raw)) return null;
334	  const port = Number(raw);
335	  return port <= MAX_PORT ? port : null;
336	}
337	
338	/** Writes one stderr line and lets the process exit with code 1 (nothing else keeps it alive). */
339	function failStartup(message) {
340	  process.stderr.write(`${message}\n`);
341	  process.exitCode = 1;
342	}
343	
344	function main() {
345	  const port = parsePort(process.env.PORT);
346	  if (port === null) return failStartup(`invalid PORT: ${process.env.PORT}`);
347	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
348	  const dataPath = path.resolve(process.cwd(), dataName);
349	  const state = loadState(dataPath);
350	  if (state === null) return failStartup(`cannot read data file ${dataName}`);
351	  const server = http.createServer(createApp(dataPath, state));
352	  server.on('error', (err) => failStartup(`cannot listen on ${HOST}:${port}: ${err.code || err.message}`));
353	  server.listen(port, HOST, () => {
354	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
355	  });
356	}
357	
358	main();
