  expectError(await post(port, big, CT('text/plain')), 415, MSG.ct, 'bad type beats big body');
  expectError(await post(port, Buffer.alloc(10001, 0x7b)), 413, MSG.big, '10001 bytes invalid JSON');
  const padded = JSON.stringify(valid()) + ' '.repeat(10001 - JSON.stringify(valid()).length);
  expectError(await post(port, padded), 413, MSG.big, '10001 bytes valid booking');
